# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_span_labels


def labels(texts, step):
    return round_span_labels(spans=[parse_span(text) for text in texts], step=step)


class RoundingTests(unittest.TestCase):
    def test_exact_times_are_unchanged(self):
        self.assertEqual(labels(['09:00-17:15'], 15), ['09:00-17:15 (8h 15m)'])

    def test_rounds_to_nearest(self):
        self.assertEqual(labels(['08:53-17:08'], 15), ['09:00-17:15 (8h 15m)'])

    def test_halfway_rounds_up(self):
        self.assertEqual(labels(['09:07-10:22'], 15), ['09:00-10:30 (1h 30m)'])

    def test_one_label_per_span_in_order(self):
        self.assertEqual(
            labels(['13:00-14:00', '09:02-10:58'], 30),
            ['13:00-14:00 (1h 0m)', '09:00-11:00 (2h 0m)'],
        )

    def test_end_of_day(self):
        self.assertEqual(labels(['23:00-24:00'], 60), ['23:00-24:00 (1h 0m)'])

    def test_empty_list(self):
        self.assertEqual(labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ProjectError):
                    labels(['09:00-10:00'], step)

    def test_span_collapsing_to_nothing_raises(self):
        with self.assertRaises(ProjectError):
            round_span_labels(spans=[Span(541, 545)], step=15)

    def test_arguments_are_keyword_only(self):
        with self.assertRaises(TypeError):
            round_span_labels([Span(0, 60)], 15)


if __name__ == '__main__':
    unittest.main()
